void ov08_022220AC(BattleParty *battleParty, u8 button);

void ov08_022220AC(BattleParty *battleParty, u8 button) {
    battleParty->useAltButtons = 0;

    if (button >= BUTTON_POKEMON_PARTY_SCREEN_POKEMON_1 && button <= BUTTON_POKEMON_PARTY_SCREEN_POKEMON_6) {
        if (ov08_0221D5DC(battleParty, button) == 2) {
            battleParty->useAltButtons = 1;
        }
    }

    battleParty->pressedButtonState = BATTLE_SUB_MENU_BUTTON_STATE_UNPRESSED;
    battleParty->sLotoId = 0;
    battleParty->pressedButton = button;
    battleParty->isAButtonPressed = 1;
}
